"""Longest Palindromic Substring — expand around every center.

There are 2n-1 centers (n single characters and n-1 gaps); each expansion is
linear, which is fast enough and far simpler than Manacher's algorithm.

Time: O(n^2)   Space: O(1)
"""


class Solution:
    def longestPalindrome(self, s: str) -> str:
        if not s:
            return ""
        start, length = 0, 1

        def expand(lo: int, hi: int) -> None:
            nonlocal start, length
            while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
                lo -= 1
                hi += 1
            if hi - lo - 1 > length:
                start, length = lo + 1, hi - lo - 1

        for i in range(len(s)):
            expand(i, i)          # odd length
            expand(i, i + 1)      # even length
        return s[start:start + length]
